.level-card::after {
  content: '';
  position: absolute;
  inset: 0;
  background: radial-gradient(circle at 85% 0%, rgba(255, 210, 63, .32), transparent 52%);
  pointer-events: none;
}
.level-card:hover { transform: translateY(-5px) rotate(-.4deg); box-shadow: 0 11px 0 var(--ink), 0 20px 30px rgba(38, 24, 10, .2); }
.level-card:active { transform: translateY(2px); box-shadow: 0 3px 0 var(--ink); }
.level-card.locked { cursor: not-allowed; background: linear-gradient(165deg, #e7e0d2, #d3cabb); color: rgba(59, 42, 24, .55); }
.level-card.locked::after { display: none; }
.level-card.locked:hover { transform: none; box-shadow: 0 7px 0 var(--ink), 0 16px 26px rgba(38, 24, 10, .14); }
.card-num {
  font-family: var(--font-display);
  font-size: 42px;
  line-height: .85;
  color: var(--ink);
  -webkit-text-stroke: 1.5px var(--ink);
  paint-order: stroke fill;
  text-shadow: 0 3px 0 rgba(59, 42, 24, .15);
}
.level-card.locked .card-num { color: rgba(59, 42, 24, .4); }
.card-art {
  position: absolute;
  right: -10px;
  top: 4px;
  width: 72px;
  height: 72px;
  opacity: .16;
  transform: rotate(10deg);
}
.card-name {
  position: relative;
  z-index: 1;
  font-family: var(--font-display);
  font-size: clamp(14px, 1.35vw, 19px);
  line-height: 1.05;
  letter-spacing: .02em;
  margin-top: 4px;
}
.card-sub {
  position: relative;
  z-index: 1;
  font-size: 10px;
  font-weight: 800;
  line-height: 1.25;
  color: var(--ink-soft);
  opacity: .85;
  margin-top: 3px;
  min-height: 24px;
}
.level-card.locked .card-sub { opacity: .6; }
.card-stars {
  position: relative;
  z-index: 1;
  display: flex;
  gap: 2px;
  margin-top: 8px;
}
.card-stars svg {
  width: 22px;
  height: 22px;
  color: rgba(59, 42, 24, .16);
  filter: drop-shadow(0 1px 0 rgba(59, 42, 24, .15));
}
.card-stars svg.on { color: var(--yellow); }
.card-lock {
  position: absolute;
  right: 12px;
  bottom: 12px;
  width: 30px;
  height: 30px;
  color: rgba(59, 42, 24, .5);
}
.card-badge {
  position: absolute;
  top: 12px;
  right: 12px;
  z-index: 2;
  padding: 3px 8px 4px;
  border: 2px solid var(--ink);
  border-radius: 7px;
  background: var(--green);
  font-family: var(--font-display);
  font-size: 11px;
  letter-spacing: .08em;
  box-shadow: 0 2px 0 var(--ink);
}

/* ---------- Modals ---------- */
.modal-screen {
  display: flex;
  align-items: center;
  justify-content: center;
  background: rgba(30, 42, 34, .45);
  backdrop-filter: blur(8px);
}
.modal-card {
  position: relative;
  width: min(92vw, 470px);
  padding: clamp(22px, 3.2vw, 34px);
  border: 4px solid var(--ink);
  border-radius: 26px;
  background:
    radial-gradient(circle at 80% 0%, rgba(255, 210, 63, .25), transparent 45%),
    linear-gradient(170deg, #fffdf5 0%, var(--cream) 55%, #ffe9bd 100%);
  box-shadow: 0 10px 0 var(--ink), 0 26px 50px rgba(20, 14, 6, .35);
  text-align: center;
  animation: cardIn .38s cubic-bezier(.2, .9, .3, 1.2) both;
}
@keyframes cardIn { from { opacity: 0; transform: translateY(24px) scale(.94) rotate(-1deg); } to { opacity: 1; transform: translateY(0) scale(1) rotate(0); } }
.modal-actions {
  display: flex;
  flex-direction: column;
  align-items: stretch;
  gap: 10px;
  margin-top: 20px;
}
.modal-actions .btn { width: 100%; }
.modal-actions .btn-ghost { padding: 8px; font-size: 15px; }
.modal-card .eyebrow { margin-bottom: 2px; }
.win-title { color: var(--green); -webkit-text-stroke: 3px var(--ink); }
.stars-big {
  display: flex;
  justify-content: center;
  gap: 6px;
  margin: 10px 0 4px;
}
.stars-big .star {
  width: clamp(44px, 6vw, 64px);
  height: clamp(44px, 6vw, 64px);
  color: rgba(59, 42, 24, .14);
  transform: scale(.7) rotate(-12deg);
  opacity: 0;
  filter: drop-shadow(0 4px 0 rgba(59, 42, 24, .18));
}
.stars-big .star:nth-child(2) { transform: scale(.7) rotate(8deg); }
.stars-big .star:nth-child(3) { transform: scale(.7) rotate(-4deg); }
.stars-big.show .star {
  animation: starPop .55s cubic-bezier(.2, .9, .3, 1.4) forwards;
}
.stars-big.show .star:nth-child(1) { animation-delay: .12s; }
.stars-big.show .star:nth-child(2) { animation-delay: .3s; }
.stars-big.show .star:nth-child(3) { animation-delay: .48s; }
.stars-big .star.on { color: var(--yellow); }
@keyframes starPop {
  0% { opacity: 0; transform: scale(.4) rotate(-30deg); }
  60% { opacity: 1; transform: scale(1.18) rotate(6deg); }
  100% { opacity: 1; transform: scale(1) rotate(0); }
}
.result-score {
  display: flex;
  flex-direction: column;
  align-items: center;
  margin-top: 8px;
}
.result-label { font-size: 10px; font-weight: 900; letter-spacing: .24em; color: var(--ink-soft); }
.result-value {
  font-family: var(--font-display);
  font-size: clamp(38px, 5.5vw, 56px);
  line-height: 1;
  letter-spacing: .03em;
  color: var(--ink);
  text-shadow: 0 3px 0 rgba(59, 42, 24, .14);
}
.result-best { font-size: 11px; font-weight: 900; letter-spacing: .14em; color: var(--ink-soft); opacity: .8; }
.egg-result {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  margin-top: 10px;
  padding: 5px 12px;
  border-radius: 999px;
  border: 2px solid rgba(59, 42, 24, .25);
  background: rgba(255, 210, 63, .22);
  font-size: 11px;
  font-weight: 900;
  letter-spacing: .06em;
  color: var(--ink-soft);
  min-height: 27px;
}
.egg-result svg { width: 15px; height: 15px; }
.egg-result.hidden { visibility: hidden; }
.lose-card { background: radial-gradient(circle at 80% 0%, rgba(233, 75, 60, .12), transparent 45%), linear-gradient(170deg, #fffdf5, var(--cream) 55%, #f7d9c9); }
.lose-card h2 { color: var(--red); -webkit-text-stroke: 3px var(--ink); }
.lose-copy { margin: 14px auto 0; max-width: 320px; font-size: 13px; font-weight: 800; color: var(--ink-soft); line-height: 1.45; }

/* ---------- Toast / hints ---------- */
.toast {
  position: absolute;
  left: 50%;
  bottom: max(26px, calc(env(safe-area-inset-bottom) + 18px));
  transform: translate(-50%, 16px) scale(.96);
  padding: 11px 22px;
  border: 3px solid var(--ink);
  border-radius: 14px;
  background: var(--cream);
  box-shadow: 0 5px 0 var(--ink), 0 12px 24px rgba(38, 24, 10, .25);
  font-weight: 900;
  font-size: clamp(11px, 1.2vw, 15px);
  letter-spacing: .03em;
  color: var(--ink);
  opacity: 0;
  visibility: hidden;
  pointer-events: none;
  transition: opacity .24s, transform .24s, visibility .24s;
  z-index: 30;
  text-align: center;
  max-width: 86vw;
}
.toast.show { opacity: 1; visibility: visible; transform: translate(-50%, 0) scale(1); }
.toast .toast-key {
  display: inline-block;
  padding: 1px 7px;
  margin: 0 2px;
  border: 2px solid var(--ink);
  border-radius: 6px;
  background: var(--yellow);
  font-size: .9em;
}

.rotate-hint {
  position: absolute;
  top: max(10px, env(safe-area-inset-top));
  left: 50%;
  transform: translateX(-50%) translateY(-80px);
  padding: 6px 12px;
  border-radius: 999px;
  border: 2px solid rgba(59, 42, 24, .3);
  background: rgba(255, 246, 223, .92);
  font-size: 10px;
  font-weight: 900;
  letter-spacing: .04em;
  color: var(--ink-soft);
  z-index: 25;
  pointer-events: none;
  transition: transform .4s ease;
}
@media (orientation: portrait) and (max-width: 820px) {
  .rotate-hint { transform: translateX(-50%) translateY(0); }
}

/* ---------- Loading ---------- */
.loading {
  position: absolute;
  inset: 0;
  z-index: 60;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 14px;
  background: #8fd8f2;
  transition: opacity .5s ease, visibility .5s;
}
.loading.done { opacity: 0; visibility: hidden; }
.loading-pig { width: 74px; height: 74px; animation: bob 1s ease-in-out infinite; }
@keyframes bob { 0%,100% { transform: translateY(0) rotate(-4deg); } 50% { transform: translateY(-12px) rotate(4deg); } }
.loading-text { font-family: var(--font-display); font-size: 18px; letter-spacing: .06em; color: var(--ink); }

/* ---------- Responsive ---------- */
@media (max-width: 900px) {
  .level-grid { grid-template-columns: repeat(3, minmax(0, 1fr)); }
  .level-card { min-height: 165px; }
  .hud .level-name { display: none; }
  .level-pill { padding-right: 10px; }
  .score-pill { min-width: 76px; }
}
@media (max-width: 640px) {
  .title-content { padding-left: 14px; padding-right: 14px; }
  .tagline { margin-top: 12px; }
  .menu-actions { margin-top: 16px; gap: 10px; }
  .btn-lg { padding: 15px 36px; }
  .howto { display: none; }
  .title-footer { margin-top: 12px; }
  .level-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 10px; padding: 12px 0; }
  .level-card { min-height: 150px; padding: 13px; border-radius: 16px; }
  .card-num { font-size: 34px; }
  .card-sub { display: none; }
  .card-stars svg { width: 18px; height: 18px; }
  .hud { padding-top: max(8px, env(safe-area-inset-top)); gap: 6px; }
  .hud-left, .hud-right { gap: 5px; }
  .icon-btn { width: 40px; height: 40px; padding: 9px; border-radius: 12px; }
  .level-pill { height: 40px; padding-left: 5px; padding-right: 8px; border-radius: 12px; }
  .level-num { width: 27px; height: 27px; font-size: 16px; border-radius: 7px; }
  .score-pill { height: 40px; padding: 0 9px; border-radius: 12px; min-width: 64px; }
  .score-value { font-size: 18px; }
  .score-label { font-size: 7px; }
  .ammo { height: 40px; padding: 0 7px; border-radius: 12px; gap: 2px; }
  .ammo-pig { width: 20px; height: 20px; }
  .ammo-pig .pip { width: 9px; height: 9px; }
  .modal-card { padding: 22px 18px; }
}
@media (max-width: 380px) {
  .score-label { display: none; }
  .score-pill { min-width: 56px; }
  .ammo-pig:nth-child(n+5) { display: none; }
}
@media (max-height: 520px) and (orientation: landscape) {
  .logo-angry { font-size: clamp(40px, 9vh, 72px); }
  .logo-pigs { font-size: clamp(52px, 12vh, 94px); }
  .swapped-badge { font-size: 15px; padding: 4px 16px 5px; }
  .tagline { margin-top: 8px; font-size: 12px; }
  .menu-actions { margin-top: 10px; }
  .btn-lg { padding: 12px 30px; font-size: 20px; }
  .btn { padding: 10px 20px; }
  .howto { margin-top: 8px; padding: 6px 12px; font-size: 10px; }
  .title-footer { display: none; }
  .eyebrow { font-size: 9px; }
  .level-grid { padding: 8px 0; }
  .level-card { min-height: 118px; padding: 10px; }
  .card-num { font-size: 30px; }
  .card-sub { display: none; }
  .card-stars svg { width: 16px; height: 16px; }
  .modal-card { padding: 16px 22px; }
  .stars-big .star { width: 36px; height: 36px; }
  .result-value { font-size: 34px; }
  .modal-actions { margin-top: 12px; gap: 7px; }
  .modal-actions .btn { padding: 9px 18px; font-size: 15px; }
}

// Tiny WebAudio synth kit — no audio files, everything is generated.
export class SoundKit {
  constructor() {
    this.ctx = null;
    this.master = null;
    this.muted = false;
    this.noiseBuffer = null;
    this.stretchOsc = null;
    this.stretchGain = null;
  }

  unlock() {
    if (this.ctx) {
      if (this.ctx.state === 'suspended') this.ctx.resume();
      return;
    }
    const AC = window.AudioContext || window.webkitAudioContext;
    if (!AC) return;
    this.ctx = new AC();
    this.master = this.ctx.createGain();
    this.master.gain.value = this.muted ? 0 : 0.55;
    this.master.connect(this.ctx.destination);

    // short noise buffer reused by impacts
    const len = Math.floor(this.ctx.sampleRate * 0.7);
    const buf = this.ctx.createBuffer(1, len, this.ctx.sampleRate);
    const data = buf.getChannelData(0);
    for (let i = 0; i < len; i++) data[i] = Math.random() * 2 - 1;
    this.noiseBuffer = buf;
  }

  setMuted(muted) {
    this.muted = muted;
    if (this.master && this.ctx) {
      this.master.gain.setTargetAtTime(muted ? 0 : 0.55, this.ctx.currentTime, 0.03);
    }
  }

  now() { return this.ctx ? this.ctx.currentTime : 0; }

  tone({ freq = 440, to = null, dur = 0.15, type = 'sine', vol = 0.3, attack = 0.005, delay = 0 }) {
    if (!this.ctx || this.muted) return;
    const t = this.now() + delay;
    const osc = this.ctx.createOscillator();
    const gain = this.ctx.createGain();
    osc.type = type;
    osc.frequency.setValueAtTime(freq, t);
    if (to != null) osc.frequency.exponentialRampToValueAtTime(Math.max(20, to), t + dur);
    gain.gain.setValueAtTime(0.0001, t);
    gain.gain.exponentialRampToValueAtTime(Math.max(0.0002, vol), t + attack);
    gain.gain.exponentialRampToValueAtTime(0.0001, t + dur);
    osc.connect(gain).connect(this.master);
    osc.start(t);
    osc.stop(t + dur + 0.02);
  }

  noise({ dur = 0.15, vol = 0.3, freq = 1200, q = 0.8, type = 'lowpass', delay = 0, sweep = null }) {
    if (!this.ctx || this.muted || !this.noiseBuffer) return;
    const t = this.now() + delay;
    const src = this.ctx.createBufferSource();
    src.buffer = this.noiseBuffer;
    const filter = this.ctx.createBiquadFilter();
    filter.type = type;
    filter.frequency.setValueAtTime(freq, t);
    if (sweep != null) filter.frequency.exponentialRampToValueAtTime(Math.max(40, sweep), t + dur);
    filter.Q.value = q;
    const gain = this.ctx.createGain();
    gain.gain.setValueAtTime(0.0001, t);
    gain.gain.exponentialRampToValueAtTime(Math.max(0.0002, vol), t + 0.008);
    gain.gain.exponentialRampToValueAtTime(0.0001, t + dur);
    src.connect(filter).connect(gain).connect(this.master);
    src.start(t, Math.random() * 0.2);
    src.stop(t + dur + 0.02);
  }

  click() {
    this.unlock();
    this.tone({ freq: 520, to: 720, dur: 0.07, type: 'triangle', vol: 0.18 });
  }

  stretchStart() {
    this.unlock();
    if (!this.ctx || this.stretchOsc) return;
    const t = this.now();
    this.stretchOsc = this.ctx.createOscillator();
    this.stretchGain = this.ctx.createGain();
    this.stretchOsc.type = 'sawtooth';
    this.stretchOsc.frequency.value = 70;
    this.stretchGain.gain.value = 0.0001;
    const filter = this.ctx.createBiquadFilter();
    filter.type = 'lowpass';
    filter.frequency.value = 500;
    this.stretchOsc.connect(filter).connect(this.stretchGain).connect(this.master);
    this.stretchOsc.start(t);
    this.stretchGain.gain.setTargetAtTime(0.035, t, 0.04);
  }

  stretchMove(power) {
    if (!this.stretchOsc || !this.ctx) return;
    const f = 60 + power * 130;
    this.stretchOsc.frequency.setTargetAtTime(f, this.now(), 0.02);
  }

  stretchStop() {
    if (!this.stretchOsc || !this.ctx) return;
    const t = this.now();
    this.stretchGain.gain.setTargetAtTime(0.0001, t, 0.03);
    this.stretchOsc.stop(t + 0.12);
    this.stretchOsc = null;
    this.stretchGain = null;
  }

  launch() {
    this.stretchStop();
    this.tone({ freq: 260, to: 80, dur: 0.22, type: 'triangle', vol: 0.38 });
    this.noise({ dur: 0.3, vol: 0.18, freq: 2200, sweep: 400, type: 'bandpass', q: 0.7 });
  }

  thud(strength = 1) {
    const s = Math.min(1.4, Math.max(0.2, strength));
    this.tone({ freq: 90 + Math.random() * 20, to: 42, dur: 0.13 + s * 0.05, type: 'sine', vol: 0.28 * s });
    this.noise({ dur: 0.1, vol: 0.1 * s, freq: 500, type: 'lowpass' });
  }

  woodBreak() {
    this.noise({ dur: 0.22, vol: 0.3, freq: 900, sweep: 240, type: 'bandpass', q: 1.1 });
    this.tone({ freq: 160, to: 70, dur: 0.12, type: 'square', vol: 0.12 });
    for (let i = 0; i < 3; i++) {
      this.noise({ dur: 0.06, vol: 0.1, freq: 1600 + Math.random() * 900, type: 'bandpass', delay: 0.03 + i * 0.04 });
    }
  }

  glassBreak() {
    this.noise({ dur: 0.18, vol: 0.24, freq: 5200, sweep: 2600, type: 'highpass' });
    for (let i = 0; i < 5; i++) {
      this.tone({
        freq: 1800 + Math.random() * 2600,
        to: 900 + Math.random() * 1000,
        dur: 0.08 + Math.random() * 0.1,
        type: 'sine',
        vol: 0.07,
        delay: 0.01 + i * 0.035,
      });
    }
  }

  stoneBreak() {
    this.noise({ dur: 0.32, vol: 0.34, freq: 700, sweep: 140, type: 'lowpass' });
    this.tone({ freq: 110, to: 48, dur: 0.2, type: 'square', vol: 0.12 });
  }

  poof() {
    this.tone({ freq: 520, to: 160, dur: 0.16, type: 'square', vol: 0.16 });
    this.noise({ dur: 0.2, vol: 0.2, freq: 2400, sweep: 600, type: 'bandpass', q: 0.6 });
    this.tone({ freq: 880, to: 1320, dur: 0.09, type: 'triangle', vol: 0.08, delay: 0.05 });
  }

  explode() {
    this.noise({ dur: 0.55, vol: 0.5, freq: 1400, sweep: 80, type: 'lowpass' });
    this.tone({ freq: 150, to: 34, dur: 0.45, type: 'sawtooth', vol: 0.3 });
    this.tone({ freq: 70, to: 30, dur: 0.6, type: 'sine', vol: 0.4 });
  }

  boost() {
    this.tone({ freq: 320, to: 880, dur: 0.16, type: 'sawtooth', vol: 0.12 });
    this.noise({ dur: 0.22, vol: 0.15, freq: 1200, sweep: 3200, type: 'bandpass' });
  }

  slam() {
    this.tone({ freq: 180, to: 44, dur: 0.28, type: 'square', vol: 0.22 });
    this.noise({ dur: 0.2, vol: 0.2, freq: 600, type: 'lowpass' });
  }

  egg() {
    const notes = [659, 784, 988, 1319];
    notes.forEach((f, i) => this.tone({ freq: f, dur: 0.28, type: 'triangle', vol: 0.16, delay: i * 0.09 }));
    this.noise({ dur: 0.5, vol: 0.05, freq: 6000, type: 'highpass' });
  }

  win() {
    const notes = [523, 659, 784, 1047, 1319];
    notes.forEach((f, i) => {
      this.tone({ freq: f, dur: 0.34, type: 'triangle', vol: 0.2, delay: i * 0.11 });
      this.tone({ freq: f / 2, dur: 0.3, type: 'sine', vol: 0.08, delay: i * 0.11 });
    });
  }

  lose() {
    const notes = [392, 349, 311, 262];
    notes.forEach((f, i) => this.tone({ freq: f, to: f * 0.94, dur: 0.34, type: 'triangle', vol: 0.17, delay: i * 0.17 }));
    this.tone({ freq: 130, to: 90, dur: 0.9, type: 'sine', vol: 0.12, delay: 0.2 });
  }

  star(index) {
    const base = [659, 784, 1047][index] || 659;
    this.tone({ freq: base, dur: 0.25, type: 'triangle', vol: 0.18 });
    this.tone({ freq: base * 2, dur: 0.18, type: 'sine', vol: 0.08, delay: 0.03 });
  }
}

