    ctx.fillStyle = 'rgba(255, 120, 110, .28)';
    for (const side of [-1, 1]) {
      ctx.beginPath();
      ctx.ellipse(side * r * 0.6, r * 0.12, r * 0.15, r * 0.1, 0, 0, Math.PI * 2);
      ctx.fill();
    }

