+    ctx.strokeStyle = 'rgba(52, 38, 24, .75)';
+    ctx.lineWidth = 2;
+    ctx.lineCap = 'round';
+    ctx.beginPath();
+    ctx.moveTo(-r * 0.2, r * 0.66);
+    ctx.quadraticCurveTo(0, r * 0.78, r * 0.2, r * 0.66);
+    ctx.stroke();
+
+    // Cheeks
+    ctx.fillStyle = 'rgba(255, 120, 110, .28)';
+    for (const side of [-1, 1]) {
+      ctx.beginPath();
