+      ctx.lineWidth = 2.6;
+      ctx.beginPath();
+      ctx.moveTo(r * 0.02, -r * 0.66);
+      ctx.quadraticCurveTo(r * 0.3, -r * 1.2, r * 0.06, -r * 1.42);
